describe('Notification Click Navigation', () => {
  beforeEach(() => {
    cy.visit('/notifications');
  });

  it('should navigate to related content when clicking a notification', () => {
    // Verify notifications are visible
    cy.get('[data-testid="notification-item"]').should('be.visible');
    cy.get('[data-testid="notification-item"]').should('have.length.greaterThan', 0);

    // Click on the first notification
    cy.get('[data-testid="notification-item"]').first().click();

    // Verify navigation to related content
    cy.url().should('include', '/content');
    cy.get('[data-testid="content-title"]').should('be.visible');
    cy.get('[data-testid="content-title"]').should('contain', 'Notification Details');

    // Verify notification is marked as read
    cy.get('[data-testid="notification-item"]').first().should('have.class', 'read');
    cy.get('[data-testid="notification-badge"]').should('not.exist');
  });

  it('should handle clicking a notification with no related content', () => {
    // Intercept API call for notification data
    cy.intercept('GET', '/api/notifications/123').as('getNotification');

    // Navigate to specific notification
    cy.visit('/notifications/123');
    cy.wait('@getNotification');

    // Verify notification is displayed
    cy.get('[data-testid="notification-item"]').should('be.visible');
    cy.get('[data-testid="notification-item"]').should('contain', 'No related content');

    // Click on the notification
    cy.get('[data-testid="notification-item"]').click();

    // Verify user is on a generic notification view, not content page
    cy.url().should('include', '/notifications');
    cy.get('[data-testid="notification-details"]').should('be.visible');
    cy.get('[data-testid="notification-details"]').should('contain', 'No related content');

    // Verify notification is still marked as unread
    cy.get('[data-testid="notification-item"]').should('not.have.class', 'read');
  });
});
